function validate([k, arrival, load]) {
  if (!Number.isInteger(k) || k < 1 || k > 100000) return 'k is between 1 and 100000.';
  if (!Array.isArray(arrival) || !Array.isArray(load)) return 'arrival and load are lists.';
  if (arrival.length < 1 || arrival.length > 100000) return 'There are 1 to 100000 requests.';
  if (arrival.length !== load.length) return 'arrival and load have the same length.';
  for (let i = 0; i < arrival.length; i++) {
    if (!Number.isInteger(arrival[i]) || arrival[i] < 1 || arrival[i] > 1000000000) return 'Each arrival time is between 1 and 10^9.';
    if (!Number.isInteger(load[i]) || load[i] < 1 || load[i] > 1000000000) return 'Each load is between 1 and 10^9.';
    if (i > 0 && arrival[i] <= arrival[i - 1]) return 'arrival must be strictly increasing.';
  }
  return null;
}

