function busiestServers(k, arrival, load) {
  const handled = new Array(k).fill(0);
  const free = Array.from({ length: k }, (_, id) => id);
  const busy = [];

  const lowerBound = (target) => {
    let left = 0;
    let right = free.length;
    while (left < right) {
      const mid = (left + right) >> 1;
      if (free[mid] < target) left = mid + 1;
      else right = mid;
    }
    return left;
  };
  const pushBusy = (item) => {
    busy.push(item);
    let i = busy.length - 1;
    while (i > 0 && busy[(i - 1) >> 1][0] > busy[i][0]) {
      const parent = (i - 1) >> 1;
      [busy[parent], busy[i]] = [busy[i], busy[parent]];
      i = parent;
    }
  };
  const popBusy = () => {
    const top = busy[0];
    const last = busy.pop();
    if (busy.length > 0) {
      busy[0] = last;
      let i = 0;
      while (2 * i + 1 < busy.length) {
        let child = 2 * i + 1;
        if (child + 1 < busy.length && busy[child + 1][0] < busy[child][0]) child++;
        if (busy[i][0] <= busy[child][0]) break;
        [busy[i], busy[child]] = [busy[child], busy[i]];
        i = child;
      }
    }
    return top;
  };

  for (let i = 0; i < arrival.length; i++) {
    while (busy.length > 0 && busy[0][0] <= arrival[i]) {
      const server = popBusy()[1];
      free.splice(lowerBound(server), 0, server);
    }
    if (free.length === 0) continue;
    let pos = lowerBound(i % k);
    if (pos === free.length) pos = 0;
    const server = free[pos];
    free.splice(pos, 1);
    handled[server]++;
    pushBusy([arrival[i] + load[i], server]);
  }
  const most = handled.reduce((best, count) => Math.max(best, count), 0);
  return handled.map((count, id) => (count === most ? id : -1)).filter((id) => id >= 0);
}

