function busiestServers(k, arrival, load) {
  const doneAt = new Array(k).fill(0);
  const count = new Array(k).fill(0);
  for (let i = 0; i < arrival.length; i++) {
    for (let step = 0; step < k; step++) {
      const server = (i + step) % k;
      if (doneAt[server] <= arrival[i]) {
        doneAt[server] = arrival[i] + load[i];
        count[server] += 1;
        break;
      }
    }
  }
  let top = 0;
  for (const c of count) if (c > top) top = c;
  const result = [];
  for (let id = 0; id < k; id++) if (count[id] === top) result.push(id);
  return result;
}

