function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = 2000;
    const k = [int(1, 5), int(5, 60), int(100, 2000)][int(0, 2)];
    const maxGap = [1, 10, 1000][int(0, 2)];
    const arrival = [];
    let time = int(1, 1000);
    for (let i = 0; i < n; i++) {
      arrival.push(time);
      time += int(1, maxGap);
    }
    const spread = Math.min(1000000000, Math.max(1, Math.round(k * maxGap * (0.5 + rand()))));
    const load = Array.from({ length: n }, () => (rand() < 0.02 ? int(1, 1000000000) : int(1, spread)));
    return [k, arrival, load];
  }
  const k = int(1, 5);
  const n = int(1, 10);
  const arrival = [];
  let time = int(1, 3);
  for (let i = 0; i < n; i++) {
    arrival.push(time);
    time += int(1, 3);
  }
  const load = Array.from({ length: n }, () => int(1, 2 * k + 3));
  return [k, arrival, load];
}
